  assign waddr_r_TRELLIS_FF_Q_CE_LUT4_Z_C[2] = wval_r_TRELLIS_FF_Q_CE_LUT4_Z_C[3];
  assign wval_r_TRELLIS_FF_Q_4_CE_LUT4_Z_C[1] = wval_r_TRELLIS_FF_Q_CE_LUT4_Z_C[3];
  assign wval_r_TRELLIS_FF_Q_9_CE_LUT4_Z_C[1] = wval_r_TRELLIS_FF_Q_CE_LUT4_Z_C[3];
  assign wval_r_TRELLIS_FF_Q_9_CE_LUT4_Z_C_LUT4_C_1_Z_LUT4_Z_D[0] = addr[8];
  assign wval_r_TRELLIS_FF_Q_9_CE_LUT4_Z_C_LUT4_C_1_Z_LUT4_Z_D_LUT4_D_Z[3] = wval_r_TRELLIS_FF_Q_CE_LUT4_Z_C[3];
  assign wval_r_TRELLIS_FF_Q_9_CE_LUT4_Z_C_LUT4_C_1_Z_LUT4_Z_D_LUT4_D_Z[1] = addr[0];
  assign wval_r_TRELLIS_FF_Q_9_CE_LUT4_Z_C_LUT4_C_1_Z_LUT4_Z_D_LUT4_D_Z[0] = addr[1];
  assign wval_r_TRELLIS_FF_Q_9_CE_LUT4_Z_C_LUT4_C_1_Z_LUT4_Z_D_LUT4_Z_D[0] = addr[5];
  assign wval_r_TRELLIS_FF_Q_CE_LUT4_Z_C[1] = addr[2];
  assign wval_r_TRELLIS_FF_Q_CE_LUT4_Z_C[0] = addr[3];
endmodule



